      "body": "<p>---</p><p><br></p><p>## 頁面 1：課程導入：木蘭詩背景</p><p>- 介紹《木蘭詩》：北朝民歌，屬於樂府詩</p><p>- 提到木蘭代父從軍的故事背景</p><p>- 《木蘭詩》如何反映北朝社會與家庭觀念</p><p>- 本課將涵蓋大意、評價與歷史意義</p><p>- 課程學習目標：理解木蘭詩內涵及其歷史意義</p><p><br></p><p>---</p><p><br></p><p>## 頁面 2：木蘭詩大意</p><p>- 木蘭代父從軍，經歷軍旅生活</p><p>- 木蘭的從軍動機：孝順、代父</p><p>- 木蘭在戰場上展現的英勇與智慧</p><p>- 十二年軍旅生涯後，選擇返回家庭，拒絕高官厚祿</p><p>- 詩歌結尾揭示木蘭真實身份，凸顯性別角色的轉換</p><p><br></p><p>---</p><p><br></p><p>## 頁面 3：木蘭詩的評價（一）文學價值</p><p>- 敘事結構完整，情節緊湊</p><p>- 語言簡潔明快，善用對比（如前後身份轉換）</p><p>- 以木蘭的視角展現女性力量與智慧</p><p>- 詩中有生動的場景描寫，如木蘭的軍旅生活與日常細節</p><p>- 抒發了個體的情感與家庭責任的關係，具有情感張力</p><p><br></p><p>---</p><p><br></p><p>## 頁面 4：木蘭詩的評價（二）社會價值</p><p>- 展現北朝時期的社會動盪與軍事背景</p><p>- 反映當時社會對孝道的強調</p><p>- 詩中木蘭代表了對家庭、國家的責任感</p><p>- 女性形象的突破，顛覆傳統性別角色</p><p>- 傳達了「忠孝兩全」的價值觀，呼應當時社會倫理</p><p><br></p><p>---</p><p><br></p><p>## 頁面 5：木蘭詩的歷史意義</p><p>- 反映北朝時期的軍事征戰背景</p><p>- 木蘭作為女性英雄形象，象徵對性別角色的挑戰</p><p>- 強調孝道，反映中國傳統家庭倫理</p><p>- 詩歌經歷代代傳承，成為經典，影響後世文化創作</p><p>- 木蘭的形象被多次改編，成為中華文化中的重要象徵</p><p><br></p><p>---</p><p><br></p><p>## 頁面 6：木蘭詩對現代的啟示</p><p>- 重新審視女性角色與性別平等</p><p>- 木蘭的勇敢、忠孝精神對現代價值觀的啟發</p><p>- 代父從軍的行為，啟發現代家庭責任感的討論</p><p>- 木蘭詩如何被現代流行文化（如電影、戲劇）改編</p><p>- 如何將木蘭的精神應用於當代社會中的各種挑戰</p><p><br></p><p>---</p><p><br></p><p>## 頁面 7：課程總結與討論</p><p>- 木蘭詩的核心精神是什麼？</p><p>- 木蘭的性別角色轉換給予了我們什麼樣的啟示？</p><p>- 木蘭在面對家庭與國家的選擇中，反映了什麼價值觀？</p><p>- 學生討論：木蘭的故事是否可以作為現代性別平等的象徵？</p><p>- 下一課將深入討論木蘭詩與其他女性英雄形象的比較</p><p><br></p><p>---</p><p><br></p><p>## 頁面 8：學習回饋與作業</p><p>- 作業：撰寫木蘭詩的讀後心得，並分析木蘭形象的多面性</p><p>- 小組討論：比較木蘭與其他歷史或文學中的女性形象</p><p>- 學生問答時間，釐清對詩歌內容與歷史意義的疑問</p><p>- 提醒學生準備下次課程：木蘭詩與現代文化的關聯</p><p>- 課堂問卷調查：本節課的收穫與建議</p>",
